public static void main(Args _args)
{
    MZNAGEnrollment enrollment;

    // Validation before Inserting
    enrollment.MZNAGScheduleId = "SCH-001";
    enrollment.MZNAGStudentId = "STU-001";
    enrollment.MZNAGEnrollmentId = "ENR003";
    enrollment.MZNAGEnrollmentStatus = MZNAGEnrollmentStatus::Enrolled;
    enrollment.EnrollmentDate = today();

    try
    {
        ttsbegin;
        enrollment.insert();
        ttscommit;

        info("Enrollment created Successfully!");
    }
    catch (Exception::DuplicateKeyException)
    {
        ttsabort;
        error("This student is already enrolled in this schedule");
    }
    catch (Exception::Error)
    {
        ttsabort;
        error("An error occurred while creating the enrollment");
    }
}
